#ifndef SC_PD_H
#define SC_PD_H

#include <stdint.h>
#include <stdbool.h>
#include "sc_hal.h"

/* The FUSB302B (usb_pd) is a PD PHY ONLY -- it does not negotiate by  */
/* itself.  Reaching the higher-voltage USB-C contract (so +VIN rises  */
/* from the 5 V default to the negotiated voltage) requires the SC to  */
/* run PD policy through the FUSB302B over I2C (BRINGUP.md Stage 1).   */
/* These are the ENTRY POINTS a PD stack (e.g. the Zephyr USB-C        */
/* subsystem or a vendored tcpm) plugs into; the protocol itself is    */
/* out of scope for this scaffold -- the hooks make the integration    */
/* point explicit and netlist-anchored (address from the contract).    */

/* Bring the FUSB302B out of reset and verify it answers on I2C.       */
/* Returns 0 on success.                                               */
int sc_pd_init(void);

/* Request a power contract of at least `min_mv` / `min_ma`.  Returns 0 */
/* once a matching contract is accepted, <0 on timeout/failure.  The   */
/* body is a STUB -- wire it to your PD policy engine.                  */
int sc_pd_request(uint32_t min_mv, uint32_t min_ma);

/* Service a PD interrupt (the FUSB302B INT is wire-ORed into SC_INT_N */
/* with the TCA9535 INT# -- read BOTH status registers on the IRQ).    */
void sc_pd_on_irq(void);

#endif /* SC_PD_H */
